#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n;scanf("%d",&n);
const int INF=1e9;
vector<int>dp(n+1,INF);dp[0]=0;
for(int i=1;i<=n;++i)
for(int j=1;j*j<=i;++j)dp[i]=min(dp[i],dp[i-j*j]+1);
printf("%d\n",dp[n]);return 0;}

